mapper.select:
/*selectMasterMdCtContractRegPopList*/ SELECT FORM_NAME ,(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'C006' AND CODE = BIZ_TYPE AND ROWNUM = 1 ) AS BIZ_TYPE ,(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'C007' AND CODE = COMPANY_TYPE AND ROWNUM = 1 ) AS COMPANY_TYPE ,DESCRIPTION ,(SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'C005' AND CODE = FORM_TYPE AND ROWNUM = 1 ) AS FORM_TYPE ,FORM_CONTENT ,WRITER_ID ,WRITER_NAME ,TO_CHAR(TO_DATE(WRITE_DATE), 'YYYY/MM/DD') AS WRITE_DATE ,(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = 'KRKORE0001' AND ROWNUM = 1) AS COMPANY_NAME
,(SELECT TO_CHAR(TO_DATE(END_DATE)+1, 'YYYY') FROM ICOMECCT WHERE CONT_NO = #{st_cont_no} AND CONT_COUNT = #{st_cont_count}) AS DATAINPUT001 ,(SELECT TO_CHAR(TO_DATE(END_DATE)+1, 'MM') FROM ICOMECCT WHERE CONT_NO = #{st_cont_no} AND CONT_COUNT = #{st_cont_count}) AS DATAINPUT002 ,(SELECT TO_CHAR(TO_DATE(END_DATE)+1, 'DD') FROM ICOMECCT WHERE CONT_NO = #{st_cont_no} AND CONT_COUNT = #{st_cont_count}) AS DATAINPUT003 ,(SELECT TO_CHAR(ADD_MONTHS(TO_DATE(END_DATE),12), 'YYYY') FROM ICOMECCT WHERE CONT_NO = #{st_cont_no} AND CONT_COUNT = #{st_cont_count}) AS DATAINPUT004 ,(SELECT TO_CHAR(ADD_MONTHS(TO_DATE(END_DATE),12), 'MM') FROM ICOMECCT WHERE CONT_NO = #{st_cont_no} AND CONT_COUNT = #{st_cont_count}) AS DATAINPUT005 ,(SELECT TO_CHAR(ADD_MONTHS(TO_DATE(END_DATE),12), 'DD') FROM ICOMECCT WHERE CONT_NO = #{st_cont_no} AND CONT_COUNT = #{st_cont_count}) AS DATAINPUT006
,TO_CHAR(SYSDATE,'YYYY') DATAINPUT001 ,TO_CHAR(SYSDATE,'MM') DATAINPUT002 ,TO_CHAR(SYSDATE,'DD') DATAINPUT003 ,TO_CHAR(ADD_MONTHS(SYSDATE,12)-1,'YYYY') DATAINPUT004 ,TO_CHAR(ADD_MONTHS(SYSDATE,12)-1,'MM') DATAINPUT005 ,TO_CHAR(ADD_MONTHS(SYSDATE,12)-1,'DD') DATAINPUT006
,TO_CHAR(SYSDATE,'YYYY') DATAINPUT007 ,TO_CHAR(SYSDATE,'MM') DATAINPUT008 ,TO_CHAR(SYSDATE,'DD') DATAINPUT009 ,ADDRESS_LOC TEXTINPUT101 ,COM_NAME_LOC TEXTINPUT102 ,CEO_NAME_LOC TEXTINPUT103 ,FORM_TYPE CONT_TYPE FROM ICOMECCF A,ICOMCMPY B WHERE A.FORM_NO = #{st_form_no} AND B.COM_CODE = #{st_com_code}

mapper.update:

INSERT INTO ICOMECCT (
	CONT_NO
	,CONT_COUNT
	,COMPANY_TYPE
	,COMPANY_CODE
	,CONT_STATUS
	,APPR_STATUS
	,FORM_NO
	,CONT_TYPE
	,BIZ_TYPE
	,CONT_CHG_TYPE
	,ATACH_UUID
	,CONTENT
	,ORI_CONTENT
	,CONT_TITLE
	,USER_ID
	,USER_NAME
	,USER_DEPT_ID
	,USER_DEPT_NAME
	,PARTNER_SIGN_DATE
	,COP_SIGN_DATE
	,CONT_DATE
	,WRITE_DATE
	,START_DATE
	,END_DATE
	,COP_ID
	,COP_NAME
	,COP_DEPT_NAME
	,COP_USER_EMAIL
	,CCO_ID
	,CCO_NAME
	,CCO_USER_MAIL
	,SPPLR_ID
	,SPPLR_NAME
	,SPPLR_USER_EMAIL
	,ADD_DATE
	,ADD_TIME
	,ADD_USER_ID
	,CHANGE_DATE
	,CHANGE_TIME
	,CHANGE_USER_ID
) VALUES (
	#{st_cont_no}
	,(SELECT NVL(MAX(CONT_COUNT),0)+1 MAX_CNT FROM ICOMECCT A WHERE A.CONT_NO = #{st_cont_no})
	,#{st_company_type}
	,#{st_com_code}
	,'TMP'
	,'A'
	,#{st_form_no}
	,#{st_cont_type}
	,#{st_biz_type}
	,#{st_cont_chg_type}
	,''
	,#{st_content}
	,#{st_oriContent}
	,#{st_contract_name}
	,#{st_user_id}
	,#{st_user_name}
	,#{st_user_deptno}
	,#{st_user_deptnm}
	,''
	,''
	,#{st_cont_date}
	,TO_CHAR(SYSDATE,'YYYYMMDD')
	,#{st_start_date}
	,#{st_end_date}
	,#{st_corp_id}
	,#{st_corp_name}
	,#{st_corp_deptnm}
	,#{st_corp_email}
	,#{st_cco_id}
	,#{st_cco_nm}
	,(SELECT EMAIL FROM ICOMLUSR WHERE COM_CODE = #{st_cco_id} AND ROWNUM = 1 AND STATUS <> 'D')
	,#{st_spplr_id}
	,#{st_spplr_nm}
	,(SELECT EMAIL FROM ICOMLUSR WHERE COM_CODE = #{st_spplr_id} AND ROWNUM = 1 AND STATUS <> 'D')
	,TO_CHAR(SYSDATE,'YYYYMMDD')
	,TO_CHAR(SYSDATE,'HH24MISS')
	,#{st_user_id}
	,TO_CHAR(SYSDATE,'YYYYMMDD')
	,TO_CHAR(SYSDATE,'HH24MISS')
	,#{st_user_id}
)
